//! 🔤️ Genuine semantic text and shipped font owners publish the shared resolved glyph path.
use crate::{PathSegment,schema::scene_preparation::{DocumentScenePlan,DocumentSceneContent,DocumentSceneError}};
use semio_framework_2d::text::font::{FontOutlineLimits,AdmittedFont,StaticFontBytes,catalog::FontCatalogAdmissionJob,run::{FontOutlineRun,FontOutlineRunCursor,FontRunStyle}};
use semio_framework_2d::text::font::shape::unicode::{UnicodeDataAdmissionJob,AdmittedUnicode,UNICODE_BYTES};
use semio_framework_value::{list::PagedList,retirement::{RetireOwned,RetirementCursor}};
fn invalid(message:impl Into<String>)->DocumentSceneError{DocumentSceneError::Invalid(message.into())}
#[derive(semio_framework_value::RetireOwned)]
struct Owners{unicode_admission:Option<UnicodeDataAdmissionJob<StaticFontBytes>>,unicode:Option<AdmittedUnicode<StaticFontBytes>>,plan:Option<DocumentScenePlan>,catalog:[Option<FontCatalogAdmissionJob>;4],fonts:[Vec<AdmittedFont<StaticFontBytes>>;4],run:Option<FontOutlineRunCursor>,completed_runs:PagedList<FontOutlineRunCursor,{usize::MAX}>,outputs:PagedList<FontOutlineRun,{usize::MAX}>,geometry:Vec<PathSegment>,failure:Option<DocumentSceneError>}
pub struct DocumentTextJob{owners:Owners,limits:FontOutlineLimits,at:usize,family:usize,phase:u8,segment:usize,total_segments:usize,work:u64,cancelled:bool}
#[derive(Clone,Copy,Debug)]
pub struct DocumentTextProgress{pub phase:&'static str,pub nodes:usize,pub work:u64,pub done:bool}
impl RetireOwned for DocumentTextJob{fn retirement(self)->Box<dyn RetirementCursor>{self.owners.retirement()}fn retirement_birth_bytes(&self)->Option<usize>{self.owners.retirement_birth_bytes()}fn controlled_retirement_supported()->bool{true}}
fn reserve<T>(list:&mut PagedList<T,{usize::MAX}>)->Result<bool,DocumentSceneError>{if list.has_reserved_slot(){return Ok(true);}let bytes=list.next_allocation_bytes().map_err(|error|invalid(error.to_string()))?;list.reserve_one(bytes).map_err(|error|invalid(error.refusal().to_string()))?;Ok(false)}
impl DocumentTextJob{
 pub fn new(plan:DocumentScenePlan,max_work:u64)->Self{let invalid_contract=plan.nodes.len()>1024||!(1..=1000000000).contains(&max_work);Self{owners:Owners{unicode_admission:None,unicode:None,plan:Some(plan),catalog:std::array::from_fn(|_|None),fonts:std::array::from_fn(|_|Vec::new()),run:None,completed_runs:PagedList::new(),outputs:PagedList::new(),geometry:Vec::new(),failure:invalid_contract.then(||invalid("Invalid text scene contract"))},limits:FontOutlineLimits{max_glyphs:65536,max_segments:65536,max_work,..Default::default()},at:0,family:0,phase:0,segment:0,total_segments:0,work:0,cancelled:false}}
 fn step(&mut self)->Result<(),DocumentSceneError>{match self.phase{
  0=>{let plan=self.owners.plan.as_ref().unwrap();let Some(node)=plan.nodes.get(self.at)else{self.phase=6;return Ok(());};if let DocumentSceneContent::Text{content,x,y,size,font_family,..}=&node.content{if self.owners.unicode.is_none(){self.owners.unicode_admission=Some(UnicodeDataAdmissionJob::new(StaticFontBytes(UNICODE_BYTES),self.limits.max_work));self.phase=7;return Ok(());}self.family=match font_family{crate::DrawingFontFamily::Anta=>0,crate::DrawingFontFamily::KellySlab=>1,crate::DrawingFontFamily::ShareTechMono=>2,crate::DrawingFontFamily::NotoEmoji=>3};if self.owners.fonts[self.family].is_empty(){if self.owners.catalog[self.family].is_none(){self.owners.catalog[self.family]=Some(FontCatalogAdmissionJob::new(font_family.catalog_family(),400,self.limits));}self.phase=1;}else{self.owners.run=Some(FontOutlineRunCursor::new(content,self.owners.fonts[self.family].len(),FontRunStyle{size:*size,origin:[*x,*y],line_height:1.2,kerning:true},self.limits,self.owners.unicode.as_ref().unwrap().layout,self.owners.unicode.as_ref().unwrap().source.0));self.phase=2;}}else{if let DocumentSceneContent::Path{segments,..}|DocumentSceneContent::Glyphs{segments,..}=&node.content{self.total_segments=self.total_segments.checked_add(segments.len()).ok_or_else(||invalid("Text scene segment authority exceeded"))?;if self.total_segments>65536{return Err(invalid("Text scene segment limit exceeded"));}}self.at+=1;}},
  7=>{let child=self.owners.unicode_admission.as_mut().unwrap();if child.advance(1).map_err(invalid)?.done{self.owners.unicode=Some(child.take_result().map_err(invalid)?);self.phase=0;}},
  1=>{let catalog=self.owners.catalog[self.family].as_mut().unwrap();if catalog.advance(1).map_err(invalid)?.done{self.owners.fonts[self.family]=catalog.take_result().map_err(invalid)?;self.phase=0;}},
  2=>{let plan=self.owners.plan.as_ref().unwrap();let DocumentSceneContent::Text{content,..}=&plan.nodes[self.at].content else{return Err(invalid("Captured semantic text changed"));};if !self.owners.run.as_mut().unwrap().advance(content,&self.owners.fonts[self.family],self.owners.unicode.as_ref().unwrap().source.0,1).map_err(invalid)?.done{return Ok(());}if !reserve(&mut self.owners.completed_runs)?{return Ok(());}if !reserve(&mut self.owners.outputs)?{return Ok(());}let output=self.owners.run.as_mut().unwrap().take_result().map_err(invalid)?;if self.total_segments.checked_add(output.segments.len()).is_none_or(|count|count>65536){self.owners.outputs.push_reserved(output).map_err(|_|invalid("Font result reservation lost"))?;return Err(invalid("Text scene segment limit exceeded"));}self.total_segments+=output.segments.len();self.owners.outputs.push_reserved(output).map_err(|_|invalid("Font result reservation lost"))?;self.owners.completed_runs.push_reserved(self.owners.run.take().unwrap()).map_err(|_|invalid("Font child reservation lost"))?;self.phase=3;},
  3=>{let output=self.owners.outputs.last().unwrap();self.owners.geometry.try_reserve_exact(output.segments.len()).map_err(|_|invalid("Glyph geometry output admission failed"))?;self.segment=0;self.phase=4;},
  4=>{let output=self.owners.outputs.last().unwrap();if let Some(segment)=output.segments.get(self.segment){self.owners.geometry.push(crate::standards::v1::subsets::any::schema::component::from_kernel_segment(segment));self.segment+=1;}else{self.phase=5;}},
  5=>{let node=&mut self.owners.plan.as_mut().unwrap().nodes[self.at];let content=std::mem::replace(&mut node.content,DocumentSceneContent::Group{children:Vec::new(),isolation:false});let DocumentSceneContent::Text{content,x,y,size,font_family,fill_rule,fill,stroke}=content else{unreachable!()};node.content=DocumentSceneContent::Glyphs{content,x,y,size,font_family,segments:std::mem::take(&mut self.owners.geometry),fill_rule,fill,stroke};self.at+=1;self.phase=0;},
  _=>return Err(invalid("Text scene stage invalid")),
 }Ok(())}
 pub fn advance(&mut self,grant:usize)->Result<DocumentTextProgress,DocumentSceneError>{if grant==0{return Err(invalid("Invalid text scene grant"));}if self.cancelled{return Err(DocumentSceneError::Cancelled);}if let Some(error)=&self.owners.failure{return Err(error.clone());}for _ in 0..grant{if self.phase==6{break;}if self.work==self.limits.max_work{self.owners.failure=Some(invalid("Text scene work limit exceeded"));return Err(self.owners.failure.as_ref().unwrap().clone());}if let Err(error)=self.step(){self.owners.failure=Some(error.clone());return Err(error);}self.work+=1;}Ok(DocumentTextProgress{phase:match self.phase{0=>"nodes",1=>"fonts",2=>"run",3=>"geometryAdmission",4=>"geometry",5=>"publishing",7=>"unicode",_=>"complete"},nodes:self.at,work:self.work,done:self.phase==6})}
 pub fn result(&self)->Result<&DocumentScenePlan,DocumentSceneError>{if self.cancelled{return Err(DocumentSceneError::Cancelled);}if let Some(error)=&self.owners.failure{return Err(error.clone());}if self.phase!=6{return Err(DocumentSceneError::Incomplete);}self.owners.plan.as_ref().ok_or(DocumentSceneError::Incomplete)}
 pub fn cancel(&mut self){self.cancelled=true;}
 pub fn into_retirement(mut self)->(DocumentTextRetirement,Option<DocumentScenePlan>){let output=if self.phase==6&&!self.cancelled&&self.owners.failure.is_none(){self.owners.plan.take()}else{None};self.cancelled=true;(DocumentTextRetirement::new(self),output)}
}
semio_framework_2d::physical_work_retirement!(DocumentTextRetirement,DocumentTextJob,DocumentSceneError,|error:&str|invalid(error));

